#!/usr/bin/env python3
"""Generate deterministic on-device JPEG images and Pillow reference pixels."""
from pathlib import Path
from io import BytesIO
import argparse
from PIL import Image

p = argparse.ArgumentParser(description=__doc__)
p.add_argument('--output', type=Path, required=True)
a = p.parse_args()
lines = ['/* SPDX-License-Identifier: Apache-2.0 */',
         '/* Generated by tools/generate_p4_jpeg_selftest.py; Pillow ' + Image.__version__ + '. */',
         '#pragma once',
         'struct jpeg_test_s { const char *name; const uint8_t *data, *reference;',
         '  size_t size; unsigned width, height; bool gray, solid; };']
cases = []
for name, w, h, sampling, gray, optimized, solid in [
    ('444', 32, 32, 0, False, False, False),
    ('422', 32, 32, 1, False, False, False),
    ('420', 32, 32, 2, False, False, False),
    ('padded', 30, 24, 2, False, False, False),
    ('optimized', 32, 32, 2, False, True, False),
    ('gray', 32, 24, 0, True, False, False),
    ('nodht', 32, 32, 2, False, False, False),
    ('wide444', 96, 32, 0, False, False, False),
    ('wide422', 96, 32, 1, False, False, False),
    ('wide420', 96, 32, 2, False, False, False),
    ('widegray', 128, 24, 0, True, False, False),
    ('large420', 1024, 600, 2, False, False, True)]:
    image = Image.new('L' if gray else 'RGB', (w, h))
    colors = [(208, 48, 48), (48, 208, 48), (48, 48, 208), (192, 176, 64)]
    image.putdata([((80, 140, 200) if solid else (x * 7 + y * 3) % 256 if gray else colors[(x // 16 + 2 * (y // 16)) % 4])
                   for y in range(h) for x in range(w)])
    stream = BytesIO()
    image.save(stream, 'JPEG', quality=90, subsampling=sampling, optimize=optimized)
    data = stream.getvalue()
    reference = Image.open(BytesIO(data)).convert('L' if gray else 'RGB').tobytes()
    if solid:
        assert all(reference[i:i+3] == reference[:3] for i in range(0, len(reference), 3))
        reference = reference[:3]
    if name == 'nodht':
        result = data[:2]
        pos = 2
        while data[pos + 1] != 0xda:
            end = pos + 2 + int.from_bytes(data[pos + 2:pos + 4], 'big')
            if data[pos + 1] != 0xc4:
                result += data[pos:end]
            pos = end
        data = result + data[pos:]
    for suffix, payload in [('data', data), ('reference', reference)]:
        lines += [f'static const uint8_t jpeg_{name}_{suffix}[] = {{']
        lines += ['  ' + ','.join(str(b) for b in payload[i:i+20]) + ','
                  for i in range(0, len(payload), 20)]
        lines += ['};']
    cases.append(f'  {{"{name}",jpeg_{name}_data,jpeg_{name}_reference,'
                 f'sizeof(jpeg_{name}_data),{w},{h},{str(gray).lower()},{str(solid).lower()}}},')
lines += ['static const struct jpeg_test_s g_jpeg_tests[] = {', *cases, '};', '']
a.output.write_text('\n'.join(lines), encoding='utf-8')
print('JPEG_SELFTEST_GENERATED', a.output)
